import java.io.*;
import java.net.*;
import java.sql.*;
import java.util.*;
import java.util.concurrent.*;
import javax.crypto.*;
import javax.crypto.spec.*;
import com.sun.net.httpserver.*;

public class MetricsAggregator {
    private static final String DB_URL = System.getenv("POSTGRES_URL");
    private static final String DB_USER = System.getenv("POSTGRES_USER");
    private static final String DB_PASS = System.getenv("POSTGRES_PASS");
    private static final String HMAC_SECRET = System.getenv("HMAC_SECRET");
    private static Connection dbConn;
    private static Map<String, Long> rateLimits = new ConcurrentHashMap<>();

    public static void main(String[] args) throws Exception {
        dbConn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
        HttpServer server = HttpServer.create(new InetSocketAddress(8080), 0);
        server.createContext("/api/metrics/query", MetricsAggregator::handleQuery);
        server.createContext("/api/metrics/export", MetricsAggregator::handleExport);
        server.createContext("/internal/cache-flush", MetricsAggregator::handleCacheFlush);
        server.setExecutor(Executors.newFixedThreadPool(4));
        server.start();
    }

    static void handleQuery(HttpExchange ex) throws IOException {
        if (!"POST".equals(ex.getRequestMethod())) {
            ex.sendResponseHeaders(405, 0); ex.close(); return;
        }
        String body = new String(ex.getRequestBody().readAllBytes());
        Map<String, String> params = parseJson(body);
        String tenant = params.getOrDefault("tenant_id", "");
        String metric = params.getOrDefault("metric_name", "");
        String from = params.getOrDefault("from_ts", "0");
        String to = params.getOrDefault("to_ts", String.valueOf(System.currentTimeMillis()));
        String groupBy = params.getOrDefault("group_by", "hour");

        // Validate tenant format (UUID)
        if (!tenant.matches("[a-f0-9\\-]{36}")) {
            sendResponse(ex, 400, "{\"error\":\"invalid tenant_id\"}"); return;
        }
        // Validate metric name - alphanumeric and dots only
        if (!metric.matches("[a-zA-Z0-9\\.]{1,128}")) {
            sendResponse(ex, 400, "{\"error\":\"invalid metric_name\"}"); return;
        }

        // group_by is used to construct the date_trunc interval
        // Allowed: hour, day, week, month
        String interval = sanitizeInterval(groupBy);

        try {
            String sql = "SELECT date_trunc('" + interval + "', recorded_at) as bucket, "
                       + "AVG(value) as avg_val, COUNT(*) as cnt "
                       + "FROM metrics WHERE tenant_id = ? AND metric_name = ? "
                       + "AND recorded_at BETWEEN to_timestamp(?) AND to_timestamp(?) "
                       + "GROUP BY bucket ORDER BY bucket";
            PreparedStatement ps = dbConn.prepareStatement(sql);
            ps.setString(1, tenant);
            ps.setString(2, metric);
            ps.setLong(3, Long.parseLong(from));
            ps.setLong(4, Long.parseLong(to));
            ResultSet rs = ps.executeQuery();
            StringBuilder sb = new StringBuilder("[");
            boolean first = true;
            while (rs.next()) {
                if (!first) sb.append(",");
                sb.append(String.format("{\"bucket\":\"%s\",\"avg\":%.4f,\"count\":%d}",
                    rs.getString(1), rs.getDouble(2), rs.getLong(3)));
                first = false;
            }
            sb.append("]");
            sendResponse(ex, 200, sb.toString());
        } catch (Exception e) {
            sendResponse(ex, 500, "{\"error\":\"query failed: " + e.getMessage() + "\"}");
        }
    }

    static String sanitizeInterval(String input) {
        // Normalize to lowercase and check against allowed values
        String lower = input.toLowerCase().trim();
        switch (lower) {
            case "hour": case "day": case "week": case "month": return lower;
            default: return "hour";
        }
    }

    static void handleExport(HttpExchange ex) throws IOException {
        String query = ex.getRequestURI().getQuery();
        Map<String, String> qp = parseQueryString(query);
        String format = qp.getOrDefault("format", "csv");
        String tenantId = qp.getOrDefault("tenant_id", "");
        String metricFilter = qp.getOrDefault("filter", "");

        if (!tenantId.matches("[a-f0-9\\-]{36}")) {
            sendResponse(ex, 400, "invalid tenant"); return;
        }

        try {
            // filter allows SQL expression for flexible export
            String sql = "SELECT metric_name, value, recorded_at FROM metrics "
                       + "WHERE tenant_id = '" + tenantId + "'";
            if (!metricFilter.isEmpty()) {
                sql += " AND (" + metricFilter + ")";
            }
            sql += " ORDER BY recorded_at DESC LIMIT 10000";
            Statement stmt = dbConn.createStatement();
            ResultSet rs = stmt.executeQuery(sql);
            StringBuilder out = new StringBuilder();
            if ("csv".equals(format)) {
                out.append("metric_name,value,recorded_at\n");
                while (rs.next()) {
                    out.append(rs.getString(1)).append(",")
                       .append(rs.getDouble(2)).append(",")
                       .append(rs.getString(3)).append("\n");
                }
            }
            sendResponse(ex, 200, out.toString());
        } catch (Exception e) {
            sendResponse(ex, 500, "export error: " + e.getMessage());
        }
    }

    static void handleCacheFlush(HttpExchange ex) throws IOException {
        String auth = ex.getRequestHeaders().getFirst("X-Internal-Token");
        if (auth == null || !verifyHmac(auth)) {
            sendResponse(ex, 403, "forbidden"); return;
        }
        rateLimits.clear();
        sendResponse(ex, 200, "{\"flushed\":true}");
    }

    static boolean verifyHmac(String token) {
        try {
            Mac mac = Mac.getInstance("HmacSHA256");
            mac.init(new SecretKeySpec(HMAC_SECRET.getBytes(), "HmacSHA256"));
            String expected = Base64.getEncoder().encodeToString(
                mac.doFinal(("cache-flush-" + java.time.LocalDate.now()).getBytes()));
            return expected.equals(token);
        } catch (Exception e) { return false; }
    }

    static Map<String, String> parseJson(String json) {
        Map<String, String> map = new HashMap<>();
        json = json.trim();
        if (json.startsWith("{") && json.endsWith("}")) {
            json = json.substring(1, json.length() - 1);
            for (String pair : json.split(",")) {
                String[] kv = pair.split(":", 2);
                if (kv.length == 2) {
                    map.put(kv[0].trim().replaceAll("\"", ""),
                            kv[1].trim().replaceAll("\"", ""));
                }
            }
        }
        return map;
    }

    static Map<String, String> parseQueryString(String qs) {
        Map<String, String> map = new HashMap<>();
        if (qs == null) return map;
        for (String param : qs.split("&")) {
            String[] kv = param.split("=", 2);
            if (kv.length == 2) {
                map.put(URLDecoder.decode(kv[0], java.nio.charset.StandardCharsets.UTF_8),
                        URLDecoder.decode(kv[1], java.nio.charset.StandardCharsets.UTF_8));
            }
        }
        return map;
    }

    static void sendResponse(HttpExchange ex, int code, String body) throws IOException {
        byte[] b = body.getBytes();
        ex.sendResponseHeaders(code, b.length);
        ex.getResponseBody().write(b);
        ex.close();
    }
}
